package main

import (
	"errors"
	"sync"
	"time"
)

// ErrNotFound is returned when a session id is unknown or has expired.
var ErrNotFound = errors.New("session not found")

// Session is one signed-in user.
type Session struct {
	ID       string
	User     string
	Created  time.Time
	LastSeen time.Time
}

// Store keeps sessions in memory. Everything is lost when the process exits.
type Store struct {
	mu       sync.RWMutex
	sessions map[string]Session
	ttl      time.Duration
	now      func() time.Time
}

// NewStore returns an empty store. Sessions idle for longer than ttl expire.
func NewStore(ttl time.Duration) *Store {
	return &Store{
		sessions: map[string]Session{},
		ttl:      ttl,
		now:      time.Now,
	}
}

// Create records a new session for a user.
func (s *Store) Create(id string, user string) Session {
	s.mu.Lock()
	defer s.mu.Unlock()
	at := s.now()
	session := Session{ID: id, User: user, Created: at, LastSeen: at}
	s.sessions[id] = session
	return session
}

// Get returns a live session and refreshes its last-seen time. An expired
// session is dropped and reported as missing.
func (s *Store) Get(id string) (Session, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	session, ok := s.sessions[id]
	if !ok {
		return Session{}, ErrNotFound
	}
	if s.now().Sub(session.LastSeen) > s.ttl {
		delete(s.sessions, id)
		return Session{}, ErrNotFound
	}
	session.LastSeen = s.now()
	s.sessions[id] = session
	return session, nil
}

// Delete removes a session. Deleting an unknown id is not an error.
func (s *Store) Delete(id string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	delete(s.sessions, id)
}

// Len reports how many sessions are held.
func (s *Store) Len() int {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return len(s.sessions)
}

package main

import (
	"testing"
	"time"
)

// clockCase is one row of a fake-clock table test.
type clockCase struct {
	name    string
	ttl     time.Duration
	advance time.Duration
	wantErr bool
	wantLen int
}

// newClockStore returns a store whose clock is frozen at 2026-01-01T00:00:00Z
// plus a function that advances that clock, so other test files can reuse the
// fake-clock plumbing without duplicating it.
func newClockStore(ttl time.Duration) (*Store, func(time.Duration)) {
	store := NewStore(ttl)
	clock := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	store.now = func() time.Time { return clock }
	advance := func(d time.Duration) { clock = clock.Add(d) }
	return store, advance
}

// runClockTable drives one fresh store per case with a fake clock that never
// sleeps, so expiry is tested deterministically. New expiry tests should reuse
// this helper instead of duplicating the fake-clock plumbing.
func runClockTable(t *testing.T, cases []clockCase) {
	t.Helper()
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			store, advance := newClockStore(tc.ttl)
			store.Create("abc", "ada")
			advance(tc.advance)
			_, err := store.Get("abc")
			if tc.wantErr && err == nil {
				t.Fatalf("Get after %s: err = nil, want an error", tc.advance)
			}
			if !tc.wantErr && err != nil {
				t.Fatalf("Get after %s: %v", tc.advance, err)
			}
			if got := store.Len(); got != tc.wantLen {
				t.Fatalf("Len after %s = %d, want %d", tc.advance, got, tc.wantLen)
			}
		})
	}
}

// TestClockTableHelperSelfCheck proves the helper itself works.
func TestClockTableHelperSelfCheck(t *testing.T) {
	runClockTable(t, []clockCase{
		{name: "under-ttl", ttl: time.Minute, advance: 30 * time.Second, wantLen: 1},
		{name: "over-ttl", ttl: time.Minute, advance: 2 * time.Minute, wantErr: true, wantLen: 0},
	})
}

